DO $$ BEGIN
  GRANT SELECT, UPDATE, INSERT ON TABLE a.b TO r;
  REVOKE INSERT, DELETE ON a.b FROM r;
  CREATE TRIGGER t1 BEFORE INSERT OR UPDATE ON a.b FOR EACH ROW EXECUTE FUNCTION f();
  CREATE POLICY p ON a.b FOR SELECT USING (true);
  CREATE RULE r1 AS ON INSERT TO a.b DO INSTEAD NOTHING;
  ALTER DEFAULT PRIVILEGES IN SCHEMA a GRANT SELECT, INSERT ON TABLES TO r;
  CREATE PUBLICATION pub FOR TABLE a.b WITH (publish = 'insert, update');
  LOCK TABLE a.b IN ROW EXCLUSIVE MODE;
  CREATE VIEW v AS SELECT a, b FROM t WHERE a > 1;
  CREATE TABLE x AS SELECT a, b FROM t WHERE a > 1;
END $$;
